SELECT supp_nation, cust_nation, ship_year, SUM(volume) AS revenue FROM (SELECT n1.n_name AS supp_nation, n2.n_name AS cust_nation, YEAR(l.l_shipdate) AS ship_year, l.l_extendedprice*(1-l.l_discount) AS volume FROM tpch_supplier s JOIN tpch_lineitem l ON s.s_suppkey=l.l_suppkey JOIN tpch_orders o ON o.o_orderkey=l.l_orderkey JOIN tpch_customer c ON c.c_custkey=o.o_custkey JOIN tpch_nation n1 ON s.s_nationkey=n1.n_nationkey JOIN tpch_nation n2 ON c.c_nationkey=n2.n_nationkey WHERE ((n1.n_name='FRANCE' AND n2.n_name='GERMANY') OR (n1.n_name='GERMANY' AND n2.n_name='FRANCE')) AND l.l_shipdate BETWEEN '1995-01-01' AND '1996-12-31') x GROUP BY supp_nation,cust_nation,ship_year ORDER BY supp_nation,cust_nation,ship_year;
